from itertools import groupby


def chunk_iterator(s: str) -> str:
    """Compress a string using run-length encoding.

    Each run of consecutive identical characters is replaced by
    the character followed by its count (count omitted when 1).

    Examples:
        "aaabbc" -> "a3b2c"
        "abcd"   -> "abcd"
        ""       -> ""
    """
    return "".join(
        char if (count := sum(1 for _ in group)) == 1 else f"{char}{count}"
        for char, group in groupby(s)
    )


# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

def test_empty_string():
    assert chunk_iterator("") == ""


def test_single_character():
    assert chunk_iterator("a") == "a"


def test_no_repeats():
    assert chunk_iterator("abcd") == "abcd"


def test_all_same():
    assert chunk_iterator("aaaa") == "a4"


def test_mixed_runs():
    assert chunk_iterator("aaabbc") == "a3b2c"


def test_single_repeats_interspersed():
    assert chunk_iterator("aabcccd") == "a2bc3d"


def test_two_char_repeat():
    assert chunk_iterator("xx") == "x2"


def test_long_run():
    assert chunk_iterator("a" * 25) == "a25"


def test_alternating():
    assert chunk_iterator("ababab") == "ababab"


def test_trailing_single():
    assert chunk_iterator("aaab") == "a3b"


def test_leading_single():
    assert chunk_iterator("baaa") == "ba3"


def test_whitespace():
    assert chunk_iterator("  aa  ") == " 2a2 2"


def test_digits_in_string():
    assert chunk_iterator("1112223") == "1322331"


def test_special_characters():
    assert chunk_iterator("!!@@@##") == "!2@3#2"


def test_preserves_order():
    original = "wwwwaaadexxxxxxywww"
    assert chunk_iterator(original) == "w4a3dex6y3w"


if __name__ == "__main__":
    import pytest

    pytest.main([__file__, "-v"])
